commands:
echo "CRITERIA:"; for d in . pkg pkg/scheduler; do for f in CODING_STANDARDS.md CLAUDE.md AGENTS.md; do [ -e "$d/$f" ] && echo "$d/$f"; done; done; echo "--- run dir";
if [ -n "${CE_REVIEW_ARTIFACT_ROOT:-}" ]; then SCRATCH_ROOT="$CE_REVIEW_ARTIFACT_ROOT"; else SCRATCH_ROOT="/tmp/compound-engineering-$(id -u)"; fi;
[ -n "${CE_REVIEW_ARTIFACT_ROOT:-}" ] || { [ ! -L "$SCRATCH_ROOT" ] && (umask 077; mkdir -p "$SCRATCH_ROOT") 2>/dev/null && [ ! -L "$SCRATCH_ROOT" ] && [ -O "$SCRATCH_ROOT" ] && [ -w "$SCRATCH_ROOT" ] || SCRATCH_ROOT="${TMPDIR:-/tmp}/compound-engineering-$(id -u)"; }
if [ -L "$SCRATCH_ROOT" ]; then echo "unsafe scratch root symlink: $SCRATCH_ROOT" >&2; exit 1; fi;
(umask 077; mkdir -p "$SCRATCH_ROOT") || exit 1;
if [ -L "$SCRATCH_ROOT" ] || [ ! -O "$SCRATCH_ROOT" ]; then echo "scratch root is not owned by the current user: $SCRATCH_ROOT" >&2; exit 1; fi;
chmod 700 "$SCRATCH_ROOT" || exit 1;
RUN_ID=$(date +%Y%m%d-%H%M%S)-$(head -c4 /dev/urandom | od -An -tx1 | tr -d ' ');
RUN_DIR="$SCRATCH_ROOT/ce-code-review/$RUN_ID";
(umask 077; mkdir -p "$RUN_DIR") || exit 1; chmod 700 "$RUN_DIR" || exit 1;
echo "$RUN_DIR";
